async function showProducts(){content.innerHTML='<div class="app-heading"><p>MASTER DATA</p><h1>Master Tabung Gas</h1><span>Kelola kode dan nama jenis tabung gas.</span></div><div class="app-data-panel"><div class="product-toolbar"><h2>Daftar Produk</h2><button class="product-add" id="product-add" type="button">+ Tambah</button></div><div class="product-search"><input id="product-search" type="search" placeholder="Cari kode atau nama tabung..." aria-label="Cari tabung gas"><span id="product-total">Memuat...</span></div><div class="product-table-wrap"><table class="product-table"><thead><tr><th>Kode</th><th>Nama Barang</th><th>Aksi</th></tr></thead><tbody id="product-list"><tr><td colspan="3">Memuat data...</td></tr></tbody></table></div></div><div id="product-editor"></div>';const list=content.querySelector('#product-list'),search=content.querySelector('#product-search'),total=content.querySelector('#product-total');let products=[];function render(){const q=search.value.trim().toLowerCase(),found=products.filter(p=>(p.code+' '+p.name).toLowerCase().includes(q));total.textContent=found.length+' produk';list.innerHTML=found.length?found.map(p=>'<tr><td class="product-code-cell">'+htmlEscape(p.code)+'</td><td class="product-name-cell">'+htmlEscape(p.name)+'</td><td class="product-action-cell">'+(role==='OWNER'?'<button type="button" class="product-action" data-product-id="'+p.id+'">Edit</button>':'—')+'</td></tr>').join(''):'<tr><td colspan="3" class="product-empty">Belum ada produk gas yang sesuai.</td></tr>'}async function load(){const{data,error}=await api.from('gas_products').select('id,code,name').order('code');if(error){list.innerHTML='<tr><td colspan="3" class="product-empty">Tidak dapat memuat data produk.</td></tr>';total.textContent='Gagal';return}products=data||[];render()}function editor(product){const panel=content.querySelector('#product-editor');panel.innerHTML='<div class="product-modal-overlay"><div class="product-modal" role="dialog" aria-modal="true" aria-label="'+(product?'Edit':'Tambah')+' Tabung Gas"><h2>'+(product?'Edit':'Tambah')+' Tabung Gas</h2><p class="note">Kode tabung dibuat otomatis saat disimpan. Isi nama tabung saja.</p><form id="product-form"><label for="product-code">Kode Tabung</label><input id="product-code" readonly placeholder="Otomatis saat disimpan"><label for="product-name">Nama Tabung</label><input id="product-name" maxlength="120" required placeholder="Contoh: LPG 3 Kg"><p class="product-error" id="product-error" role="alert"></p><div class="product-actions"><button type="button" id="product-cancel">Batal</button><button class="product-save" id="product-save" type="submit">Simpan</button></div></form></div></div>';panel.querySelector('#product-code').value=product?.code||'';panel.querySelector('#product-name').value=product?.name||'';const close=()=>panel.replaceChildren();panel.querySelector('#product-cancel').onclick=close;panel.querySelector('.product-modal-overlay').addEventListener('click',e=>{if(e.target.classList.contains('product-modal-overlay'))close()});panel.querySelector('#product-form').onsubmit=async e=>{e.preventDefault();const name=panel.querySelector('#product-name').value.trim(),msg=panel.querySelector('#product-error'),save=panel.querySelector('#product-save');if(!name){msg.textContent='Nama tabung harus diisi.';return}save.disabled=true;msg.textContent='Menyimpan...';const request=product?api.from('gas_products').update({name}).eq('id',product.id):api.from('gas_products').insert({name});const{error}=await request;if(error){msg.textContent=error.code==='23505'?'Kode tabung sudah digunakan.':error.message;save.disabled=false;return}close();await load()};panel.querySelector('#product-name').focus()}const addButton=content.querySelector('#product-add');if(role!=='OWNER')addButton.remove();else addButton.onclick=()=>editor(null);search.oninput=render;list.onclick=e=>{const btn=e.target.closest('[data-product-id]');if(btn){const p=products.find(x=>x.id===btn.dataset.productId);if(p&&role==='OWNER')editor(p)}};await load()}

